#!/usr/bin/env python3
"""
A Woody Allen-inspired philosophical quote with visual flair.
Neurotic, existential, and visually entertaining!
"""

import time
import sys
import random

# ANSI color codes
class Colors:
    RESET = '\033[0m'
    BOLD = '\033[1m'
    ITALIC = '\033[3m'
    UNDERLINE = '\033[4m'
    
    # Foreground colors
    BLACK = '\033[30m'
    RED = '\033[31m'
    GREEN = '\033[32m'
    YELLOW = '\033[33m'
    BLUE = '\033[34m'
    MAGENTA = '\033[35m'
    CYAN = '\033[36m'
    WHITE = '\033[37m'
    
    # Bright foreground
    BRIGHT_BLACK = '\033[90m'
    BRIGHT_RED = '\033[91m'
    BRIGHT_GREEN = '\033[92m'
    BRIGHT_YELLOW = '\033[93m'
    BRIGHT_BLUE = '\033[94m'
    BRIGHT_MAGENTA = '\033[95m'
    BRIGHT_CYAN = '\033[96m'
    BRIGHT_WHITE = '\033[97m'

def slow_print(text, delay=0.03, color=Colors.RESET, end='\n'):
    """Print text slowly with typewriter effect"""
    for char in text:
        sys.stdout.write(color + char)
        sys.stdout.flush()
        time.sleep(delay)
    sys.stdout.write(Colors.RESET + end)
    sys.stdout.flush()

def print_border(char='═', length=60, color=Colors.CYAN):
    """Print a decorative border"""
    border = char * length
    print(color + border + Colors.RESET)

def animate_title():
    """Animate the title with color changes"""
    title = "A WOODY ALLEN-ESQUE EXISTENTIAL CRISIS"
    colors = [Colors.YELLOW, Colors.MAGENTA, Colors.CYAN, Colors.GREEN, Colors.RED]
    
    print("\n")
    for i, char in enumerate(title):
        color = colors[i % len(colors)]
        sys.stdout.write(color + char)
        sys.stdout.flush()
        time.sleep(0.08)
    print(Colors.RESET + "\n")
    time.sleep(0.5)

def main():
    # Clear screen (works on most systems)
    print("\033[2J\033[H", end="")
    
    # Animated title
    animate_title()
    
    # Print decorative border
    print_border('◆', 60, Colors.MAGENTA)
    print()
    
    # The Woody Allen quote (original creation)
    quote = (
        "I always thought that if I had a second chance at life, "
        "I would have done things differently. But then I realized "
        "that I probably would have messed it up again anyway. "
        "Which makes me wonder if the universe is just one big "
        "cosmic joke, and I'm the punchline that never quite lands. "
        "But then again, maybe that's what makes it all worth living for - "
        "the terrible jokes, the existential dread, and the occasional "
        "moment of clarity that makes you realize you're still here, "
        "still breathing, still telling terrible jokes to yourself "
        "in the mirror at 3 AM."
    )
    
    # Print quote with typewriter effect
    words = quote.split()
    current_line = ""
    max_line_length = 70
    
    print(Colors.BOLD + Colors.BRIGHT_WHITE + "    \"", end="")
    
    for i, word in enumerate(words):
        test_line = current_line + (" " if current_line else "") + word
        if len(test_line) > max_line_length:
            # Print current line
            slow_print(current_line, delay=0.02, color=Colors.BRIGHT_CYAN, end="")
            print()
            print(Colors.BOLD + Colors.BRIGHT_WHITE + "    ", end="")
            current_line = word
        else:
            current_line = test_line
    
    # Print the last line
    if current_line:
        slow_print(current_line, delay=0.02, color=Colors.BRIGHT_CYAN, end="")
    
    print(Colors.BOLD + Colors.BRIGHT_WHITE + "\"")
    print()
    
    # Print author attribution
    print_border('◇', 60, Colors.MAGENTA)
    print()
    
    attribution = "— A Neurotic Reflection on Existence"
